sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {
	var url = gs.getProperty("glide.servlet.uri");
	url+= "nav_to.do?uri=%2Fx_hccc_hoc_ohs_investigation_case.do%3Fsys_id%3D";
	url+= current.sys_id;		url+="%26sysparm_record_list%3DORDERBYDESCsys_created_on%26sysparm_record_row%3D1%26sysparm_record_rows%3D759%26sysparm_record_target%3Dx_hccc_hoc_ohs_investigation_case%26sysparm_view%3DWorkplace_Incident_Reporting%26sysparm_view_forced%3Dtrue";
	template.print("<a href='" + url+ "' target='_blank' rel='noopener'>link</a> below to view and action this case.</p>");

	})(current, template, email, email_action, event);
